Prool lets us run multiple test cases at once by creating separate isolated environments for each, with their own Bundler, Anvil, and Paymaster.To make this easier, we’ll create a helper called testWithRpc that finds free ports and spins up the isolated test environment. 




let ports: number[] = [];


	rpc: {
		anvilRpc: string;
		altoRpc: string;
		paymasterRpc: string;
	};
}&gt;({
	rpc: async ({}, use) =&gt; {
		const altoPort = await getPort({
			exclude: ports,
		});
		ports.push(altoPort);
		const paymasterPort = await getPort({
			exclude: ports,
		});
		ports.push(paymasterPort);
		const anvilPort = await getPort({
			exclude: ports,
		});
		ports.push(anvilPort);

		const anvilRpc = `http://localhost:${anvilPort}`;
		const altoRpc = `http://localhost:${altoPort}`;
		const paymasterRpc = `http://localhost:${paymasterPort}`;

		const forkUrl = process.env.FORK_RPC_URL || base.rpcUrls.default.http[0];

		const instances = await getInstances({
			forkUrl,
			anvilPort,
			altoPort,
			paymasterPort,
		});

		await use({
			anvilRpc,
			altoRpc,
			paymasterRpc,
		});

		await Promise.all([...instances.map((instance) =&gt; instance.stop())]);
		const usedPorts = [altoPort, anvilPort, paymasterPort];
		ports = ports.filter((port) =&gt; !usedPorts.includes(port));
	},
}); 


